-- Tambahkan kolom yang ada di database lokal tetapi belum ada pada dump server.
DELIMITER //
DROP PROCEDURE IF EXISTS `migrasi_lengkapi_kolom_pembayaran_faktur`//
CREATE PROCEDURE `migrasi_lengkapi_kolom_pembayaran_faktur`()
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'tbkeu_pembayaran_faktur'
          AND COLUMN_NAME = 'skema_potongan_z'
    ) THEN
        ALTER TABLE `tbkeu_pembayaran_faktur`
            ADD COLUMN `skema_potongan_z` int NOT NULL DEFAULT 0;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'tbkeu_pembayaran_faktur'
          AND COLUMN_NAME = 'no_faktur_konsinyasi'
    ) THEN
        ALTER TABLE `tbkeu_pembayaran_faktur`
            ADD COLUMN `no_faktur_konsinyasi` varchar(50) DEFAULT NULL;
    END IF;
END//
CALL `migrasi_lengkapi_kolom_pembayaran_faktur`()//
DROP PROCEDURE `migrasi_lengkapi_kolom_pembayaran_faktur`//
DELIMITER ;
